FeatureScript 3112;
import(path : "onshape/std/geometry.fs", version : "3112.0");

// Fixture batch 189: more curved faces replaced. Generated by tools/fixtures/gen-batch-189.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

function round6(v) returns array
{
    return [roundToPrecision(v[0] / millimeter, 6), roundToPrecision(v[1] / millimeter, 6), roundToPrecision(v[2] / millimeter, 6)];
}

// Knot arrays, weights and control point matrices are typed: indexed, as std does, rather than iterated.
function numbersProbe(numbers) returns array
{
    var out = [];
    for (var i = 0; i < size(numbers); i += 1)
        out = append(out, roundToPrecision(numbers[i], 9));
    return out;
}

function bsplineProbe(s) returns map
{
    var b = { "uDegree" : s.uDegree, "vDegree" : s.vDegree, "rational" : s.isRational };
    try
    {
        b.uKnots = numbersProbe(s.uKnots);
        b.vKnots = numbersProbe(s.vKnots);
    }
    catch (error)
    {
        b.knots = "failed";
    }
    try
    {
        const matrix = s.controlPoints;
        var rows = [];
        for (var i = 0; i < size(matrix); i += 1)
        {
            var points = [];
            for (var j = 0; j < size(matrix[i]); j += 1)
                points = append(points, round6(matrix[i][j]));
            rows = append(rows, points);
        }
        b.poles = rows;
    }
    catch (error)
    {
        b.poles = "failed";
    }
    return b;
}

// Each face of a body: its area, its surface's type, and for a B-spline its degrees, knots and poles.
function faceProbe(context is Context, body is Query) returns array
{
    var out = [];
    for (var face in evaluateQuery(context, qOwnedByBody(body, EntityType.FACE)))
    {
        var entry = { "area" : roundToPrecision(evArea(context, { "entities" : face }) / millimeter ^ 2, 6) };
        try
        {
            const s = evSurfaceDefinition(context, { "face" : face });
            entry["type"] = s.surfaceType;
            if (s is BSplineSurface)
                entry.bspline = bsplineProbe(s);
        }
        catch (error)
        {
            entry["type"] = "failed";
        }
        out = append(out, entry);
    }
    return out;
}

// Each edge of a body that isn't straight: its ends and middle, and for a B-spline its degree, knots, poles and
// weights.
function curveProbe(context is Context, body is Query) returns array
{
    var out = [];
    const edges = qOwnedByBody(body, EntityType.EDGE);
    for (var edge in evaluateQuery(context, qSubtraction(edges, qGeometry(edges, GeometryType.LINE))))
    {
        var entry = {};
        try
        {
            const lines = evEdgeTangentLines(context, { "edge" : edge, "parameters" : [0, 0.5, 1], "arcLengthParameterization" : false });
            var points = [];
            for (var l in lines)
                points = append(points, round6(l.origin));
            entry.points = points;
        }
        catch (error)
        {
            entry.points = "failed";
        }
        try
        {
            const c = evCurveDefinition(context, { "edge" : edge });
            if (c is BSplineCurve)
            {
                entry.degree = c.degree;
                entry.rational = c.isRational;
                entry.knots = numbersProbe(c.knots);
                var poles = [];
                for (var i = 0; i < size(c.controlPoints); i += 1)
                    poles = append(poles, round6(c.controlPoints[i]));
                entry.poles = poles;
                if (c.isRational)
                    entry.weights = numbersProbe(c.weights);
            }
        }
        catch (error)
        {
            entry.curve = "failed";
        }
        out = append(out, entry);
    }
    return out;
}

// replace-face: a 20 × 20 × 10 block, its top edge along y = 20 filleted to radius 3, the fillet replaced up to the plane through its ends (a chamfer)
export function c001(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(20, 20) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    fillet(context, id + "fillet1", { "entities" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(10, 20, 10) * millimeter), "radius" : 3 * millimeter });
    opPlane(context, id + "target", { "plane" : plane(vector(10, 18.5, 8.5) * millimeter, vector(0, 0.707107, 0.707107), vector(1, 0, 0)), "width" : 100 * millimeter, "height" : 100 * millimeter });
    replaceFace(context, id + "replace1", { "replaceFaces" : qGeometry(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), GeometryType.CYLINDER), "templateFace" : qCreatedBy(id + "target", EntityType.FACE), "oppositeSense" : false, "offset" : 0 * millimeter });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID)), "volume" : roundToPrecision(evVolume(context, { "entities" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID) }) / millimeter ^ 3, 6) };
}

// replace-face: a 20 × 20 × 10 plate with a hole of radius 4 through its middle, the hole replaced up to a coaxial cylinder of radius 3
export function c002(context is Context, id is Id)
{
    const s = newSketchOnPlane(context, id + "s", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(s, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(20, 20) * millimeter });
    skCircle(s, "hole", { "center" : vector(10, 10) * millimeter, "radius" : 4 * millimeter });
    skSolve(s);
    extrude(context, id + "base", { "entities" : qContainsPoint(qSketchRegion(id + "s"), vector(2, 2, 0) * millimeter), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    const toolSketch = newSketchOnPlane(context, id + "toolSketch", { "sketchPlane" : plane(vector(0, 0, -5) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(toolSketch, "circle1", { "center" : vector(10, 10) * millimeter, "radius" : 3 * millimeter });
    skSolve(toolSketch);
    extrude(context, id + "tool", { "entities" : qSketchRegion(id + "toolSketch"), "endBound" : BoundingType.BLIND, "depth" : 20 * millimeter });
    replaceFace(context, id + "replace1", { "replaceFaces" : qGeometry(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), GeometryType.CYLINDER), "templateFace" : qGeometry(qOwnedByBody(qBodyType(qCreatedBy(id + "tool", EntityType.BODY), BodyType.SOLID), EntityType.FACE), GeometryType.CYLINDER), "oppositeSense" : false, "offset" : 0 * millimeter });
