// replace-face: a 20 mm square at z = 0 lofted to a circle of radius 8 at z = 20, the side on the square's edge along x = 10 replaced up to the plane x = 8
export function c004(context is Context, id is Id)
{
    const p0 = newSketchOnPlane(context, id + "p0", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(p0, "rect1", { "firstCorner" : vector(-10, -10) * millimeter, "secondCorner" : vector(10, 10) * millimeter });
    skSolve(p0);
    const p1 = newSketchOnPlane(context, id + "p1", { "sketchPlane" : plane(vector(0, 0, 20) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(p1, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 8 * millimeter });
    skSolve(p1);
    loft(context, id + "base", { "sheetProfilesArray" : [{ "sheetProfileEntities" : qSketchRegion(id + "p0") }, { "sheetProfileEntities" : qSketchRegion(id + "p1") }], "bodyType" : ExtendedToolBodyType.SOLID, "operationType" : NewBodyOperationType.NEW, "startCondition" : LoftEndDerivativeType.DEFAULT, "endCondition" : LoftEndDerivativeType.DEFAULT });
    opPlane(context, id + "target", { "plane" : plane(vector(8, 0, 10) * millimeter, vector(1, 0, 0), vector(0, 1, 0)), "width" : 100 * millimeter, "height" : 100 * millimeter });
    replaceFace(context, id + "replace1", { "replaceFaces" : qSubtraction(qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(10, 0, 0) * millimeter), qGeometry(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), GeometryType.PLANE)), "templateFace" : qCreatedBy(id + "target", EntityType.FACE), "oppositeSense" : false, "offset" : 0 * millimeter });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID)), "volume" : roundToPrecision(evVolume(context, { "entities" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID) }) / millimeter ^ 3, 6) };
}

